<script>
    export default {
        data() {
            return {
                limitPosition: 1,
                scrolled: false,
                lastPosition: 0,
                colorfill: false
            }
        },
        methods: {
            handleScroll() {
                if (this.lastPosition < window.scrollY && this.limitPosition < window.scrollY) {
                    this.scrolled = true;
                    this.colorfill = false;
                    // move up!
                } 
                
                if (this.lastPosition > window.scrollY) {
                    this.scrolled = false;
                    // move down
                }
                
                this.lastPosition = window.scrollY;
                // this.scrolled = window.scrollY > 250;
                this.colorfill = window.scrollY > 10;
            }
        },
        created() {
            window.addEventListener("scroll", this.handleScroll);
        },
        destroyed() {
            window.removeEventListener("scroll", this.handleScroll);
        }
    }
</script>

<style>
    .headroom {
        will-change: transform;
        transition: transform 200ms linear;
    }
    .headroom--pinned {
        transform: translateY(0%);
    }
    .headroom--unpinned {
        transform: translateY(-100%);
    }
    .icons ul li svg path {
        fill: #383838 !important;
    }.icons ul li:hover .facebook {
        fill: #1f7bf2 !important;
    }.icons ul li:hover .instagram {
        fill: #fff !important;
    }.icons ul li:hover .telegram {
        fill: #38ABE2 !important;
    }.icons ul li:hover .youtube {
        fill: #ff0808 !important;
    }
</style>